"use client"

/** Gauge, optional record row, and tone-colored mini stats. */

import * as React from "react"
import { useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { RadialGauge } from "@/components/ui/radial-gauge"
import type { StatusTone } from "@/lib/status-tone"

export type ScoreStat = { id: string; label: string; value: number | string; tone?: StatusTone }

export type ScoreCardProps = {
  title: string
  chip?: React.ReactNode
  value: number
  max?: number
  caption?: string
  surface?: "accent" | "neutral"
  record?: { title: string; meta: string }
  stats?: readonly ScoreStat[]
  className?: string
}

const statTone: Record<StatusTone, string> = {
  neutral: "text-foreground",
  accent: "text-primary",
  warning: "text-chart-4",
  critical: "text-destructive",
  info: "text-chart-2",
  positive: "text-primary",
}

function useCount(value: number) {
  const reduced = useReducedMotion() ?? false
  const [shown, setShown] = React.useState(value)
  const from = React.useRef(value)
  React.useEffect(() => {
    if (reduced) {
      from.current = value
      return
    }
    const startValue = from.current
    const start = performance.now()
    let frame = 0
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / 400)
      const next = Math.round(startValue + (value - startValue) * t)
      setShown(next)
      if (t < 1) frame = requestAnimationFrame(tick)
      else from.current = value
    }
    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
  }, [reduced, value])
  return reduced ? value : shown
}

export function ScoreCard({
  title,
  chip,
  value,
  max = 100,
  caption,
  surface = "neutral",
  record,
  stats = [],
  className,
}: ScoreCardProps) {
  const shown = useCount(value)
  return (
    <section data-slot="score-card" className={cn("flex min-w-0 flex-col gap-3 rounded-2xl bg-card p-3", className)}>
      <header className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-medium">{title}</h3>
        {chip}
      </header>
      <div className={cn("rounded-xl px-3 py-2", surface === "accent" ? "bg-primary/15" : "bg-muted")}>
        <RadialGauge
          variant="ticks"
          value={shown}
          max={max}
          label={caption ?? title}
          ticks={36}
          tone="neutral"
          suffix="%"
          formatter={(next) => String(Math.round(next))}
          classNames={{ value: "text-4xl", label: "text-xs" }}
        />
      </div>
      {record ? (
        <div className="flex items-center justify-between gap-2 rounded-xl bg-card px-1 text-sm">
          <span className="truncate">{record.title}</span>
          <span className="shrink-0 font-mono text-xs text-muted-foreground">{record.meta}</span>
        </div>
      ) : null}
      {stats.length ? (
        <div className="grid grid-cols-3 gap-2">
          {stats.map((stat) => (
            <div key={stat.id} className="min-w-0 rounded-xl bg-muted px-2 py-2">
              <p className={cn("font-mono text-lg tabular-nums", statTone[stat.tone ?? "neutral"])}>{stat.value}</p>
              <p className="truncate text-[10px] text-muted-foreground">{stat.label}</p>
            </div>
          ))}
        </div>
      ) : null}
    </section>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { cn } from "@/lib/utils"
import { clampRatio, formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type RadialGaugeTone = "primary" | "neutral" | "destructive"

export type RadialGaugeClassNames = {
  root?: string
  value?: string
  label?: string
  over?: string
  ticks?: string
}

export type RadialGaugeProps = {
  value: number
  min?: number
  max?: number
  /** Accessible name for the meter. */
  label: string
  ticks?: number
  format?: DashboardFormat
  formatter?: (value: number) => string
  locale?: string
  currency?: string
  overLabel?: string
  tone?: RadialGaugeTone
  /** arc keeps the needle. ticks is a needle-less semicircle of marks. */
  variant?: "arc" | "ticks"
  /** Shown after the value on the ticks variant, for example "%". */
  suffix?: string
  className?: string
  classNames?: RadialGaugeClassNames
}

const CX = 100
const CY = 96
const RADIUS = 74

function point(angle: number, radius: number) {
  return {
    x: CX + Math.cos(angle) * radius,
    y: CY - Math.sin(angle) * radius,
  }
}

function arcPath(radius: number) {
  const start = point(Math.PI, radius)
  const end = point(0, radius)
  return `M ${start.x.toFixed(2)} ${start.y.toFixed(2)} A ${radius} ${radius} 0 0 1 ${end.x.toFixed(2)} ${end.y.toFixed(2)}`
}

const toneClass: Record<RadialGaugeTone, string> = {
  primary: "stroke-primary text-primary",
  neutral: "stroke-muted-foreground text-muted-foreground",
  destructive: "stroke-destructive text-destructive",
}

export function RadialGauge({
  value,
  min = 0,
  max = 100,
  label,
  ticks = 5,
  format = "number",
  formatter,
  locale = "en-US",
  currency = "USD",
  overLabel = "Over budget",
  tone = "primary",
  variant = "arc",
  suffix,
  className,
  classNames,
}: RadialGaugeProps) {
  const safeMax = max > min ? max : min + 1
  const over = value > max
  const ratio = clampRatio(value, min, safeMax)
  const clamped = value < min || value > max
  const angle = Math.PI * (1 - ratio)
  const needle = point(angle, RADIUS - 10)
  const hub = point(angle, 8)
  const text = formatter ? formatter(value) : formatDashboardValue(value, format, locale, currency)
  const tickCount = variant === "ticks" ? Math.max(12, Math.min(48, Math.round(ticks))) : Math.max(2, Math.min(9, Math.round(ticks)))
  const marks = Array.from({ length: tickCount }, (_, index) => {
    const at = Math.PI * (1 - index / (tickCount - 1))
    const outer = point(at, RADIUS + 2)
    const inner = point(at, RADIUS - 8)
    return { outer, inner, key: index }
  })
  const valuetext = over ? `${text}, ${overLabel}` : text
  const filledTicks = Math.round(ratio * tickCount)

  if (variant === "ticks") {
    return (
      <div
        data-slot="radial-gauge"
        data-variant="ticks"
        data-state={over ? "over" : "ok"}
        data-tone={over ? "destructive" : tone}
        role="meter"
        aria-label={label}
        aria-valuenow={value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={valuetext}
        className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
      >
        <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
          <g className={classNames?.ticks}>
            {marks.map((mark) => (
              <line
                key={mark.key}
                x1={mark.inner.x}
                y1={mark.inner.y}
                x2={mark.outer.x}
                y2={mark.outer.y}
                className={mark.key < filledTicks ? "stroke-foreground" : "stroke-muted-foreground/30"}
                strokeWidth="2.5"
                strokeLinecap="round"
              />
            ))}
          </g>
        </svg>
        <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>
          {text}
          {suffix ? <span className="align-super text-sm">{suffix}</span> : null}
        </p>
        <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      </div>
    )
  }

  return (
    <div
      data-slot="radial-gauge"
      data-state={over ? "over" : "ok"}
      data-tone={over ? "destructive" : tone}
      role="meter"
      aria-label={label}
      aria-valuenow={value}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={valuetext}
      className={cn("@container flex min-w-0 flex-col items-center gap-1 text-foreground", className, classNames?.root)}
    >
      <svg viewBox="0 0 200 118" className="h-auto w-full max-w-xs" aria-hidden>
        <path d={arcPath(RADIUS)} className="fill-none stroke-muted" strokeWidth="8" strokeLinecap="round" />
        <path
          d={arcPath(RADIUS)}
          pathLength={100}
          className={cn("fill-none", over ? "stroke-destructive" : toneClass[tone])}
          strokeWidth="8"
          strokeLinecap="round"
          strokeDasharray={`${ratio * 100} 100`}
        />
        <g className={classNames?.ticks}>
          {marks.map((mark) => (
            <line
              key={mark.key}
              x1={mark.inner.x}
              y1={mark.inner.y}
              x2={mark.outer.x}
              y2={mark.outer.y}
              className="stroke-muted-foreground"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          ))}
        </g>
        <line
          data-slot="radial-gauge-needle"
          data-clamped={clamped ? "true" : "false"}
          x1={hub.x}
          y1={hub.y}
          x2={needle.x}
          y2={needle.y}
          className={over ? "stroke-destructive" : "stroke-foreground"}
          strokeWidth="2.5"
          strokeLinecap="round"
        />
        <circle cx={CX} cy={CY} r="4" className={over ? "fill-destructive" : "fill-foreground"} />
      </svg>
      <p className={cn("text-3xl font-normal tabular-nums tracking-tight", over && "text-destructive", classNames?.value)}>{text}</p>
      <p className={cn("text-xs text-muted-foreground", classNames?.label)}>{label}</p>
      {over ? <p className={cn("text-xs font-medium text-destructive", classNames?.over)}>{overLabel}</p> : null}
    </div>
  )
}

/** Number, date, and greeting helpers for dashboard pieces. No theme tokens. */

export type DashboardFormat = "number" | "currency" | "percent" | "compact" | "text" | "points"

export function formatDashboardValue(
  value: number | string,
  format: DashboardFormat = "text",
  locale = "en-US",
  currency = "USD",
): string {
  if (typeof value !== "number" || !Number.isFinite(value) || format === "text") return String(value)
  if (format === "currency") {
    return new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
      notation: Math.abs(value) >= 10000 ? "compact" : "standard",
      maximumFractionDigits: Math.abs(value) >= 10000 ? 1 : 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(locale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value)
  }
  if (format === "compact") {
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value)
  }
  if (format === "points") {
    const formatted = new Intl.NumberFormat(locale, {
      signDisplay: "exceptZero",
      maximumFractionDigits: 1,
    }).format(value)
    return `${formatted} pts`
  }
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatDashboardDate(
  value: string | number | Date,
  locale = "en-US",
  options: Intl.DateTimeFormatOptions = { month: "short", day: "numeric" },
): string {
  const date = value instanceof Date ? value : new Date(value)
  if (Number.isNaN(date.getTime())) return String(value)
  return new Intl.DateTimeFormat(locale, options).format(date)
}

export function joinMeta(parts: Array<string | number | null | undefined | false>): string {
  return parts.filter((part) => part != null && part !== false && part !== "").map(String).join(" · ")
}

const DAY_PART = {
  en: { morning: "Good morning", afternoon: "Good afternoon", evening: "Good evening" },
  es: { morning: "Buenos días", afternoon: "Buenas tardes", evening: "Buenas noches" },
} as const

/** Time-of-day greeting. Spanish locales use es; everything else uses en. */
export function greeting(date: Date, locale: string, name: string): string {
  const hour = date.getHours()
  const part = hour < 12 ? "morning" : hour < 18 ? "afternoon" : "evening"
  const table = locale.toLowerCase().startsWith("es") ? DAY_PART.es : DAY_PART.en
  return `${table[part]}, ${name}`
}

export function shareOf(value: number, total: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(total) || total <= 0) return 0
  return value / total
}

export function clampRatio(value: number, min: number, max: number): number {
  const span = max - min
  if (!Number.isFinite(span) || span <= 0) return 0
  return Math.min(1, Math.max(0, (value - min) / span))
}

export type RankedInput = { id: string; value: number; share?: number }

export function orderRanked<T extends RankedInput>(items: readonly T[], sort: "asc" | "desc" | "none" = "desc"): T[] {
  const copy = items.map((item) => ({ ...item }))
  if (sort === "asc") copy.sort((a, b) => a.value - b.value || a.id.localeCompare(b.id))
  if (sort === "desc") copy.sort((a, b) => b.value - a.value || a.id.localeCompare(b.id))
  const total = copy.reduce((sum, item) => sum + (Number.isFinite(item.value) ? item.value : 0), 0)
  return copy.map((item) => ({ ...item, share: item.share ?? shareOf(item.value, total) }))
}

/** Delay in seconds for a short opacity stagger. Zero when motion is reduced. */
export function staggerDelay(index: number, reduced: boolean, step = 0.04): number {
  if (reduced || index <= 0) return 0
  return index * step
}
